var maskCredential = (val) => {
  if (!val) return "";
  try {
    const decrypted = decrypt(val);
    if (!decrypted) return "";
    if (decrypted.length <= 8) return "********";
    return `${decrypted.slice(0, 4)}****${decrypted.slice(-4)}`;
  } catch (e) {
    return "";
  }
};
