// src/middleware/subscription-enforcer.middleware.ts
init_logger();
var subscriptionEnforcerMiddleware = async (req, res, next) => {
  try {
    const tenantId = req.tenantId || req.user?.tenantId || req.headers["x-tenant-id"];
    if (!tenantId) {
      return next();
    }
    if (req.user?.role === "SUPER_ADMIN" || req.user?.role === "PLATFORM_OWNER") {
      return next();
    }
    const path3 = req.originalUrl || req.url;
    if (path3.includes("/api/v1/subscription/renew") || path3.includes("/api/v1/subscription/status") || path3.includes("/api/v1/checkout") || path3.includes("/api/v1/auth/login") || path3.includes("/api/v1/enterprise/quote")) {
      return next();
    }
    const evalResult = await SubscriptionEnforcementService.evaluateSubscriptionStatus(tenantId);
    if (!evalResult.isAccessAllowed) {
      logger_default.warn(`[SubscriptionEnforcer] Access BLOCKED for tenant ${tenantId}. Status: ${evalResult.status}. Target URL: ${path3}`);
      return res.status(402).json({
        error: "PAYMENT_REQUIRED",
        message: evalResult.statusMessage,
        subscriptionStatus: evalResult.status,
        renewUrl: "/renew",
        daysRemaining: evalResult.daysRemaining
      });
    }
    if (evalResult.status === "GRACE_PERIOD") {
      res.setHeader("X-Subscription-Warning", "GRACE_PERIOD_ACTIVE");
      res.setHeader("X-Subscription-Days-Remaining", String(evalResult.daysRemaining));
    }
    req.subscriptionEval = evalResult;
    return next();
  } catch (error) {
    logger_default.error(`[SubscriptionEnforcer] Error evaluating subscription: ${error.message}`);
    return next();
  }
};

